UPDATE TB_ST_01
   SET ST01_STOK = #{stock}
    , st01_district = #{st01District}
WHERE 1=1
AND st01_company = #{company}
AND st01_factory = #{factory}
 AND st01_lot_seq = #{lotSeq}

UPDATE tb_st_01
 -- 재고수량을 변경하는 경우
   SET st01_qty = st01_qty - #{outQty} + #{ipQty}

 -- 재고 차감 (출고등록/입고삭제)
   SET st01_qty =  st01_qty - #{outQty}

 -- 재고 증가 (입고등록/출고삭제)
   SET st01_qty =  st01_qty + #{ipQty}

 -- 재고실사 품목일때 기존의 수량 0
   SET st01_qty = '0'

WHERE 1=1
AND st01_company = #{company}
AND st01_factory = #{factory}
AND st01_code = #{code}
AND st01_stok = #{stock}

   AND st01_lot = #{lot}
   AND st01_lot_seq = #{lotSeq}
